CREATE TABLE ezcontentbrowsebookmark (id INT AUTO_INCREMENT NOT NULL, node_id INT DEFAULT 0 NOT NULL, user_id INT DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT '' NOT NULL, INDEX ezcontentbrowsebookmark_location (node_id), INDEX ezcontentbrowsebookmark_user (user_id), INDEX ezcontentbrowsebookmark_user_location (user_id, node_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
